L6_1.m_fTalkTime = 0.03
L7_1 = "\229\144\155\227\129\140\227\131\169\227\130\164\227\130\171\229\144\155\227\129\174\227\129\147\227\129\168\227\129\167\232\190\155\227\129\132\227\129\174\227\129\175\227\130\143\227\129\139\227\129\163\227\129\166\227\129\132\227\130\139\227\129\140\227\128\129\228\187\138\229\186\166\227\129\174\232\169\166\229\144\136\227\129\175\229\144\155\227\129\174\229\189\185\229\137\178\227\129\140\227\129\168\227\129\166\227\130\130\233\135\141\232\166\129\227\129\160\227\128\130"
