L6_1.m_Talk_VTN = L7_1
L7_1 = "\230\136\145\231\159\165\233\129\147\232\142\177\229\141\161\231\154\132\228\186\139\232\174\169\228\189\160\229\190\136\231\151\155\232\139\166\239\188\140\228\189\134\232\191\153\230\172\161\231\154\132\230\175\148\232\181\155\228\184\173\228\189\160\230\156\137\233\157\158\229\184\184\233\135\141\232\166\129\231\154\132\228\189\156\231\148\168\227\128\130"
