L41_1 = "m_SubTitle_ENG"
L42_1 = "<color=#ffd34c>\226\150\160\226\150\160\226\150\160\226\150\160</color> C.O. knights! LOL! That's insane!\n<color=#ffd34c>\226\150\160\226\150\160</color> But seriously, why are they so fixated with medieval knights anyway?\n<color=#ffd34c>\226\150\160 \226\150\160</color> Aren't C.O.s supposed to look like monsters or something?\n<color=#ffd34c>\226\150\160\226\150\160</color> I heard that there are C.O.s that look exactly like humans in the hyperdepths.\n<color=#ffd34c>\226\150\160\226\150\160</color> Is that why Delta Seven called for help? LOL!\n<color=#ffd34c>\226\150\160\226\150\160</color> Let's go, Canary! Kill those C.O.s by ramming them with your ship again!\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160\226\150\160</color> Sounds like that's a lot of Eternium, no? LOL!"
