L40_1[L41_1] = L42_1
L41_1 = "m_SubTitle_DEU"
L42_1 = "<color=#ffd34c>\226\150\160\226\150\160\226\150\160\226\150\160</color> Ritter-C.\194\176O.s?! LOL! Was soll das denn sein?\n<color=#ffd34c>\226\150\160\226\150\160</color> Warum haben sie sich denn ein mittelalterliches Ritterkonzept ausgesucht?\n<color=#ffd34c>\226\150\160 \226\150\160</color> Sind C.\194\176O.s nicht eigentlich Monster und keine Ritter?\n<color=#ffd34c>\226\150\160\226\150\160</color> Ich habe geh\195\182rt, dass es in den Hypertiefen C.\194\176O.s gibt, die wie Menschen aussehen.\n<color=#ffd34c>\226\150\160\226\150\160</color> Ist das der Grund, warum Delta Seven um Hilfe gerufen hat? LOL!\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> Na los, Canary Trupp! Rammt euer Schiff in diese C.\194\176O.s und macht sie damit platt!\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160\226\150\160</color> Das Eternium muss ja echt s\195\188\195\159 schmecken. Haha!"
L40_1[L41_1] = L42_1
