L42_1 = "<color=#ffd34c>\226\150\160\226\150\160\226\150\160\226\150\160</color> Les Chevaliers O.C. ? lol Trop chelou ce concept\n<color=#ffd34c>\226\150\160\226\150\160</color> S\195\169rieusement ? C'est quoi ce concept de chevaliers m\195\169di\195\169vaux l\195\160 ?\n<color=#ffd34c>\226\150\160 \226\150\160</color> Mais les O.C. c'est pas des genre de monstres ?\n<color=#ffd34c>\226\150\160\226\150\160</color> Askip, y'a des O.C. qui ressemblent \195\160 des humains dans les hyperprofondeurs\n<color=#ffd34c>\226\150\160\226\150\160</color> C'est pour \195\167a que les Delta Seven ont demand\195\169 de l'aide lol\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160</color> H\195\169, les canaris ! Vous devriez d\195\169foncer tous ces O.C. avec votre vaisseau comme l'autre fois !\n<color=#ffd34c>\226\150\160\226\150\160\226\150\160\226\150\160</color> Il va pleuvoir de l'\195\169ternium mdr"
